# frozen_string_literal: true

# Preventive maintenance plan of a contract. Dates come from
# Preventive::Schedule; occurrences are generated by
# Preventive::GenerateOccurrences with a stable identity (plan, sequence).
class MaintenancePlan < TenantRecord
  MODES = { "calendar" => "Calendário fixo", "after_completion" => "Após a conclusão da anterior" }.freeze

  belongs_to :contract, inverse_of: :maintenance_plans
  belongs_to :customer
  belongs_to :service_location
  belongs_to :service_type, optional: true
  belongs_to :created_by, class_name: "Membership", foreign_key: :created_by_membership_id, optional: true, inverse_of: false
  has_many :plan_equipment, class_name: "MaintenancePlanEquipment", dependent: nil, inverse_of: :maintenance_plan
  has_many :equipment, through: :plan_equipment
  has_many :occurrences, -> { order(sequence: :desc) }, class_name: "MaintenanceOccurrence", dependent: nil,
    inverse_of: :maintenance_plan

  normalizes :title, with: ->(value) { value.to_s.squish }

  validates :title, presence: true, length: { maximum: 160 }
  validates :frequency_unit, inclusion: { in: Preventive::Frequency::UNITS.keys }
  validates :frequency_interval, numericality: { only_integer: true, in: 1..104 }
  validates :schedule_mode, inclusion: { in: MODES.keys }
  validates :priority, inclusion: { in: WorkOrder::PRIORITIES.keys }
  validates :lead_days, numericality: { only_integer: true, in: 0..90 }
  validates :anchor_date, presence: true

  scope :active, -> { where(active: true) }

  def frequency = Preventive::Frequency.new(unit: frequency_unit, interval: frequency_interval)
  def schedule = Preventive::Schedule.new(anchor_date:, anchor_sequence:, frequency:)
  def mode_label = MODES.fetch(schedule_mode)
  def after_completion? = schedule_mode == "after_completion"
  def next_sequence = last_sequence + 1

  # Projected due date of the next occurrence (calendar plans).
  def next_due_on = after_completion? && last_sequence.positive? ? nil : schedule.due_on([next_sequence, anchor_sequence].max)
end
